     6	public class ReservationEventPublisher {
     7	    private final List<ReservationObserver> observers = new ArrayList<>();
     8	
     9	    public void attach(ReservationObserver observer) {
    10	        if (!observers.contains(observer)) {
    11	            observers.add(observer);
    12	        }
    13	    }
    14	
    15	    public void detach(ReservationObserver observer) {
    16	        observers.remove(observer);
    17	    }
    18	
    19	    public void notify(ReservationEvent event) {
    20	        for (ReservationObserver observer : new ArrayList<>(observers)) {
    21	            observer.onReservationEvent(event);
    22	        }
    23	    }
    24	}
