    93	        }
    94	
    95	        Reservation previousState = copyReservation(reservation);
    96	        reservation.setStatus(ReservationStatus.CONFIRMED);
    97	        reservation.setAmountPaid(reservation.getTotal());
    98	
    99	        eventPublisher.notify(new ReservationEvent(ReservationEventType.CONFIRMED, reservation, previousState));
   100	
   101	        return reservation;
