   104	    public Reservation cancelReservation(long id) {
   105	        Reservation reservation = getReservation(id);
   106	
   107	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
   108	            reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
   109	            throw new ApiException("OPERATION_NOT_ALLOWED",
   110	                    "Não é possível cancelar uma reserva após o check-in", 409);
   111	        }
   112	
   113	        if (reservation.getStatus() == ReservationStatus.CANCELLED) {
   114	            throw new ApiException("OPERATION_NOT_ALLOWED",
   115	                    "Reserva já está cancelada", 409);
   116	        }
   117	
   118	        Reservation previousState = copyReservation(reservation);
   119	        reservation.setStatus(ReservationStatus.CANCELLED);
   120	
   121	        BigDecimal refundAmount = BigDecimal.ZERO;
   122	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   123	            refundAmount = reservation.getAmountPaid();
   124	        }
   125	        reservation.setRefund(refundAmount);
   126	
   127	        eventPublisher.notify(new ReservationEvent(ReservationEventType.CANCELLED, reservation, previousState));
   128	
   129	        return reservation;
   130	    }
