   146	
   147	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   148	            throw new ApiException("OPERATION_NOT_ALLOWED",
   149	                    "Apenas reservas com check-in podem fazer check-out", 409);
   150	        }
   151	
   152	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
