   160	    private boolean isRoomAvailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   161	        return reservations.values().stream()
   162	                .filter(r -> r.getRoomNumber().equals(roomNumber))
   163	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   164	                .noneMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   165	    }
   166	
   167	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   168	        return start1.isBefore(end2) && start2.isBefore(end1);
   169	    }
