=== service/ReservationService.java
     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.exception.ApiException;
     4	import com.pousadamarealta.model.*;
     5	import com.pousadamarealta.observer.ReservationEvent;
     6	import com.pousadamarealta.observer.ReservationEventPublisher;
     7	import com.pousadamarealta.observer.ReservationEventType;
     8	
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.temporal.ChronoUnit;
    12	import java.util.*;
    13	import java.util.concurrent.atomic.AtomicLong;
    14	
    15	public class ReservationService {
    16	    private final Map<String, Room> rooms = new HashMap<>();
    17	    private final Map<Long, Reservation> reservations = new HashMap<>();
    18	    private final AtomicLong nextId = new AtomicLong(1);
    19	    private final PricingService pricingService;
    20	    private final ReservationEventPublisher eventPublisher;
    21	
    22	    public ReservationService(PricingService pricingService, ReservationEventPublisher eventPublisher) {
    23	        this.pricingService = pricingService;
    24	        this.eventPublisher = eventPublisher;
    25	        initializeRooms();
    26	    }
    27	
    28	    private void initializeRooms() {
    29	        rooms.put("101", new Room("101", RoomType.STANDARD));
    30	        rooms.put("102", new Room("102", RoomType.STANDARD));
    31	        rooms.put("201", new Room("201", RoomType.DELUXE));
    32	        rooms.put("202", new Room("202", RoomType.DELUXE));
    33	        rooms.put("301", new Room("301", RoomType.SUITE));
    34	    }
    35	
    36	    public List<Room> getAllRooms() {
    37	        return new ArrayList<>(rooms.values());
    38	    }
    39	
    40	    public Room getRoom(String number) {
    41	        Room room = rooms.get(number);
    42	        if (room == null) {
    43	            throw new ApiException("ROOM_NOT_FOUND", "Quarto não encontrado", 404);
    44	        }
    45	        return room;
    46	    }
    47	
    48	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    49	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    50	                                        int guests, RatePlan ratePlan) {
    51	        Room room = getRoom(roomNumber);
    52	
    53	        if (guests < 1) {
    54	            throw new ApiException("INVALID_REQUEST", "Número de hóspedes deve ser pelo menos 1", 400);
    55	        }
    56	
    57	        if (guests > room.getCapacity()) {
    58	            throw new ApiException("CAPACITY_EXCEEDED",
    59	                    "Número de hóspedes excede a capacidade do quarto", 422);
    60	        }
    61	
    62	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    63	            throw new ApiException("ROOM_UNAVAILABLE", "Quarto não disponível nas datas solicitadas", 409);
    64	        }
    65	
    66	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    67	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
    68	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    69	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    70	
    71	        long id = nextId.getAndIncrement();
    72	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
    73	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
    74	
    75	        reservations.put(id, reservation);
    76	        return reservation;
    77	    }
