  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.api.dto.*;
  7	import com.pousadamarealta.exception.ApiException;
  8	import com.pousadamarealta.model.Reservation;
  9	import com.pousadamarealta.observer.*;
 10	import com.pousadamarealta.service.EmailService;
 11	import com.pousadamarealta.service.PricingService;
 12	import com.pousadamarealta.service.ReportService;
 13	import com.pousadamarealta.service.ReservationService;
 14	import io.javalin.Javalin;
 15	import io.javalin.http.Context;
 16	import io.javalin.http.HttpStatus;
 17	import io.javalin.json.JavalinJackson;
 18	
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeParseException;
 22	import java.util.stream.Collectors;
 23	
 24	public class Application {
 25	    public static void main(String[] args) {
 26	        EmailService emailService = new EmailService();
 27	        PricingService pricingService = new PricingService();
 28	        ReservationEventPublisher eventPublisher = new ReservationEventPublisher();
 29	        ReservationService reservationService = new ReservationService(pricingService, eventPublisher);
 30	        ReportService reportService = new ReportService(reservationService);
 31	
 32	        eventPublisher.attach(new GuestNotificationObserver(emailService, reservationService));
 33	        eventPublisher.attach(new HousekeepingNotificationObserver(emailService));
 34	        eventPublisher.attach(new FinanceNotificationObserver(emailService));
 35	
 36	        ObjectMapper objectMapper = new ObjectMapper()
 37	                .registerModule(new JavaTimeModule())
 38	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 39	
 40	        int port = getPort();
 41	
 42	        Javalin app = Javalin.create(config -> {
 43	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 44	        }).start(port);
 45	
 46	        app.get("/rooms", ctx -> {
 47	            var rooms = reservationService.getAllRooms().stream()
 48	                    .map(RoomResponse::from)
 49	                    .collect(Collectors.toList());
 50	            ctx.json(rooms);
 51	        });
 52	
 53	        app.post("/reservations", ctx -> {
 54	            try {
 55	                CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 56	                validateCreateReservationRequest(request);
 57	
 58	                LocalDate checkIn = LocalDate.parse(request.getCheckIn());
 59	                LocalDate checkOut = LocalDate.parse(request.getCheckOut());
 60	
 61	                if (!checkOut.isAfter(checkIn)) {
 62	                    throw new ApiException("INVALID_REQUEST", "A data de saída deve ser após a data de entrada", 400);
 63	                }
 64	
 65	                Reservation reservation = reservationService.createReservation(
 66	                        request.getRoomNumber(),
 67	                        request.getGuestName(),
 68	                        request.getGuestEmail(),
 69	                        request.getGuestCpf(),
 70	                        checkIn,
 71	                        checkOut,
 72	                        request.getGuests(),
 73	                        request.getRatePlan()
 74	                );
 75	
 76	                ctx.status(HttpStatus.CREATED);
 77	                ctx.json(ReservationResponse.from(reservation));
 78	            } catch (DateTimeParseException e) {
 79	                throw new ApiException("INVALID_REQUEST", "Formato de data inválido. Use yyyy-MM-dd", 400);
 80	            } catch (NullPointerException e) {
 81	                throw new ApiException("INVALID_REQUEST", "Campos obrigatórios faltando", 400);
 82	            }
 83	        });
 84	
 85	        app.get("/reservations/{id}", ctx -> {
 86	            long id = parseLongOrThrow(ctx, "id");
 87	            Reservation reservation = reservationService.getReservation(id);
 88	            ctx.json(ReservationResponse.from(reservation));
 89	        });
 90	
 91	        app.post("/reservations/{id}/confirmation", ctx -> {
 92	            long id = parseLongOrThrow(ctx, "id");
 93	            Reservation reservation = reservationService.confirmReservation(id);
 94	            ctx.json(ReservationResponse.from(reservation));
 95	        });
 96	
 97	        app.post("/reservations/{id}/cancellation", ctx -> {
 98	            long id = parseLongOrThrow(ctx, "id");
 99	            Reservation reservation = reservationService.cancelReservation(id);
100	            ctx.json(ReservationResponse.from(reservation));
101	        });
102	
103	        app.post("/reservations/{id}/check-in", ctx -> {
104	            long id = parseLongOrThrow(ctx, "id");
105	            Reservation reservation = reservationService.checkIn(id);
106	            ctx.json(ReservationResponse.from(reservation));
107	        });
108	
109	        app.post("/reservations/{id}/check-out", ctx -> {
110	            long id = parseLongOrThrow(ctx, "id");
111	            Reservation reservation = reservationService.checkOut(id);
112	            String roomType = reservationService.getRoom(reservation.getRoomNumber()).getType().name();
113	            ctx.json(ReceiptResponse.from(reservation, roomType));
