 10	public class PricingService {
 11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 13	
 14	    public BigDecimal calculateNightlyPrice(Room room, LocalDate date) {
 15	        BigDecimal basePrice = room.getNightlyRate();
 16	        if (isHighSeason(date)) {
 17	            return round(basePrice.multiply(HIGH_SEASON_MULTIPLIER));
 18	        }
 19	        return basePrice;
 20	    }
 21	
 22	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
 23	        BigDecimal subtotal = BigDecimal.ZERO;
 24	        LocalDate date = checkIn;
 25	        while (date.isBefore(checkOut)) {
 26	            BigDecimal nightPrice = calculateNightlyPrice(room, date);
 27	            subtotal = subtotal.add(nightPrice);
 28	            date = date.plusDays(1);
 29	        }
 30	        return round(subtotal);
 31	    }
 32	
 33	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
 34	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
 35	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 36	        }
 37	        return BigDecimal.ZERO;
 38	    }
 39	
 40	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 41	        return round(subtotal.subtract(discount));
 42	    }
 43	
 44	    private boolean isHighSeason(LocalDate date) {
 45	        int month = date.getMonthValue();
 46	        int day = date.getDayOfMonth();
 47	
 48	        if (month == 7) {
 49	            return true;
 50	        }
 51	
 52	        if (month == 12 && day >= 15) {
 53	            return true;
 54	        }
 55	
 56	        if (month == 1 || month == 2) {
 57	            return true;
 58	        }
 59	
 60	        return false;
 61	    }
 62	
 63	    private BigDecimal round(BigDecimal value) {
 64	        return value.setScale(2, RoundingMode.HALF_EVEN);
 65	    }
 66	}
