 81	public class ReportService {
 82	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 83	
 84	    private final ReservationService reservationService;
 85	
 86	    public ReportService(ReservationService reservationService) {
 87	        this.reservationService = reservationService;
 88	    }
