101	
102	        for (Reservation reservation : occupiedReservations) {
103	            Room room = reservationService.getRoom(reservation.getRoomNumber());
104	            csv.append(String.format("%s,%s,%d,%s,%s\n",
105	                    reservation.getRoomNumber(),
106	                    room.getType(),
107	                    reservation.getId(),
108	                    reservation.getCheckIn().format(DATE_FORMAT),
109	                    reservation.getCheckOut().format(DATE_FORMAT)));
110	        }
111	
112	        int totalRooms = reservationService.getAllRooms().size();
113	        int occupiedRooms = occupiedReservations.size();
114	        csv.append(String.format("total,%d/%d", occupiedRooms, totalRooms));
115	
116	        return csv.toString();
117	    }
118	
119	    public String generateRevenueReport(YearMonth month) {
120	        StringBuilder csv = new StringBuilder();
121	        csv.append("reservation,room,check_in,check_out,status,amount\n");
122	
123	        List<Reservation> relevantReservations = reservationService.getAllReservations().stream()
124	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
125	                .filter(r -> {
126	                    BigDecimal revenue = calculateRevenue(r);
127	                    return revenue.compareTo(BigDecimal.ZERO) > 0;
128	                })
129	                .sorted(Comparator.comparing(Reservation::getCheckIn)
130	                        .thenComparing(Reservation::getId))
131	                .collect(Collectors.toList());
132	
133	        BigDecimal totalRevenue = BigDecimal.ZERO;
134	
135	        for (Reservation reservation : relevantReservations) {
136	            BigDecimal revenue = calculateRevenue(reservation);
137	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
138	                    reservation.getId(),
139	                    reservation.getRoomNumber(),
140	                    reservation.getCheckIn().format(DATE_FORMAT),
141	                    reservation.getCheckOut().format(DATE_FORMAT),
142	                    reservation.getStatus(),
143	                    formatAmount(revenue)));
144	            totalRevenue = totalRevenue.add(revenue);
145	        }
146	
147	        csv.append(String.format("total,%s", formatAmount(totalRevenue)));
148	
149	        return csv.toString();
150	    }
151	
152	    private BigDecimal calculateRevenue(Reservation reservation) {
153	        BigDecimal revenue = reservation.getAmountPaid();
154	        if (reservation.getRefund() != null) {
155	            revenue = revenue.subtract(reservation.getRefund());
156	        }
157	        return revenue;
158	    }
159	
160	    private String formatAmount(BigDecimal amount) {
161	        return amount.stripTrailingZeros().toPlainString();
162	    }
163	}

